    setDialog(null);setSelectedOrder({...o,id:"OS-"+dbOrder.order_number,createdAt:dbOrder.created_at??new Date().toISOString(),dbId:dbOrder.id});setOrders(v=>[{...o,id:"OS-"+dbOrder.order_number,createdAt:dbOrder.created_at??new Date().toISOString(),dbId:dbOrder.id},...v]);if(part)setStock(v=>v.map(s=>s.id===part.id?{...s,quantity:s.quantity-part.quantity}:s));window.setTimeout(()=>setDialog("orderView"),180);
